// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount, uint256 extra) public {
        amount = bound(amount, 1, 1e30);
        extra = bound(extra, 0, 1e30);

        address user = address(0x1000);
        vm.deal(user, amount + extra);

        vm.prank(user);
        c.deposit{value: amount + extra}();

        uint256 balanceBefore = address(c).balance;

        vm.prank(user);
        c.withdraw(amount);

        uint256 balanceAfter = address(c).balance;

        assertTrue(balanceBefore - balanceAfter == amount);
    }
}
